package cn.shixu.app.test;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.net.Uri;
import android.os.*;
import android.provider.MediaStore;
import android.view.accessibility.AccessibilityNodeInfo;
import cn.shixu.app.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;

/** Real bundled model tests using only synthetic notification images. */
public class OcrInstrumentation extends SmokeInstrumentation {
    boolean waitText(String text){for(int i=0;i<90;i++){if(has(text))return true;pause();}return false;}
    boolean createEnabled(){for(AccessibilityNodeInfo node:nodes())if(node.getContentDescription()!=null&&"用识别文字生成事项".contentEquals(node.getContentDescription()))return node.isEnabled();return false;}
    Bitmap notice(){Bitmap image=Bitmap.createBitmap(1100,720,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(image);canvas.drawColor(Color.WHITE);Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);p.setColor(Color.BLACK);p.setTextSize(46);String[] lines={"活动通知","请大家明天上午9:00-10:30","在教学楼301教室参加读书交流会。","请带上笔记本，准时到场。"};for(int n=0;n<lines.length;n++)canvas.drawText(lines[n],60,110+n*115,p);return image;}
    Uri save(Context c,byte[] bytes,String mime,List<Uri> cleanup)throws IOException{ContentValues values=new ContentValues();values.put(MediaStore.Images.Media.DISPLAY_NAME,"拾序OCR虚构通知-"+UUID.randomUUID()+(mime.equals("image/png")?".png":".jpg"));values.put(MediaStore.Images.Media.MIME_TYPE,mime);if(Build.VERSION.SDK_INT>=29){values.put(MediaStore.Images.Media.RELATIVE_PATH,"Pictures/ShixuOcrTests");values.put(MediaStore.Images.Media.IS_PENDING,1);}Uri uri=c.getContentResolver().insert(MediaStore.Images.Media.EXTERNAL_CONTENT_URI,values);if(uri==null)throw new IOException("Cannot create test image");cleanup.add(uri);try(OutputStream out=c.getContentResolver().openOutputStream(uri)){out.write(bytes);}if(Build.VERSION.SDK_INT>=29){ContentValues ready=new ContentValues();ready.put(MediaStore.Images.Media.IS_PENDING,0);c.getContentResolver().update(uri,ready,null,null);}return uri;}
    byte[] png(Bitmap bitmap){ByteArrayOutputStream out=new ByteArrayOutputStream();bitmap.compress(Bitmap.CompressFormat.PNG,100,out);return out.toByteArray();}
    void choose(Uri uri)throws IntentFilter.MalformedMimeTypeException{IntentFilter filter=new IntentFilter(Intent.ACTION_OPEN_DOCUMENT);filter.addCategory(Intent.CATEGORY_OPENABLE);filter.addDataType("image/*");ActivityMonitor monitor=addMonitor(filter,new ActivityResult(Activity.RESULT_OK,new Intent().setData(uri)),true);try{clickDescription("选择图片进行文字识别");}finally{removeMonitor(monitor);}}
    String recognize(Context c,Uri uri,boolean expectText)throws InterruptedException{CountDownLatch ready=new CountDownLatch(1);String[] value={null};boolean[] thumbnail={false};OcrEngine.recognize(c,uri,new OcrEngine.Listener(){public void preview(Bitmap image){thumbnail[0]=Math.max(image.getWidth(),image.getHeight())<=320;}public void text(String text){value[0]=text;ready.countDown();}public void error(String message){value[0]="ERROR:"+message;ready.countDown();}});check(ready.await(50,TimeUnit.SECONDS),"OCR callback finishes");if(expectText){check(value[0]!=null&&!value[0].startsWith("ERROR:"),"Bundled OCR produces text");check(thumbnail[0],"Thumbnail uses bounded size");}else check(value[0]!=null&&value[0].startsWith("ERROR:"),"Blank image returns readable error");return value[0];}
    @Override public void onStart(){Bundle results=new Bundle();Context c=getTargetContext();List<Uri> cleanup=new ArrayList<>();int outcome=Activity.RESULT_OK;try{
        int baseline;try(Store store=new Store(c)){baseline=store.all().size();}
        check(c.checkSelfPermission("android.permission.INTERNET")==android.content.pm.PackageManager.PERMISSION_DENIED,"OCR app has no internet permission");check(c.checkSelfPermission("android.permission.READ_MEDIA_IMAGES")==android.content.pm.PackageManager.PERMISSION_DENIED,"No broad photo permission requested");
        Bitmap image=notice();Uri normal=save(c,png(image),"image/png",cleanup);try(FileOutputStream out=new FileOutputStream(new File(c.getExternalFilesDir(null),"ocr-fictional-notice.png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}
        startActivitySync(new Intent(c,MainActivity.class).setFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));waitForIdleSync();check(waitText("事项清单"),"Home ready");clickDescription("从图片识别事项");check(waitText("图片识别")&&!createEnabled(),"Photo entry opens empty OCR page");
        clickDescription("切换照片增强识别");check(has("图片增强：已开启"),"Enhancement can be enabled before selecting a picture");clickDescription("切换照片增强识别");check(has("图片增强：已关闭"),"Standard recognition remains available");clickDescription("选择图片进行文字识别");pause();AccessibilityNodeInfo picker=getUiAutomation().getRootInActiveWindow();check(picker!=null&&!c.getPackageName().contentEquals(picker.getPackageName()),"System document picker opens");getUiAutomation().executeShellCommand("input keyevent 4").close();check(waitText("选择一张图片开始识别。")&&!createEnabled(),"Cancelling picker preserves empty state");
        choose(normal);check(waitText("识别完成，请核对文字"),"Selected PNG completes real OCR");check(has("读书交流会")&&has("301"),"Recognized Chinese and classroom number visible");check(createEnabled(),"Nonempty recognition enables create");capture(c,"ocr-review-proof.png");
        String raw="";for(AccessibilityNodeInfo node:nodes())if("android.widget.EditText".contentEquals(node.getClassName()))raw=node.getText().toString();setEdit(0,raw.replace("救室","教室")+"\n备注：虚构测试，请带上水杯。");check(has("请带上水杯"),"OCR text can be corrected before extraction");clickDescription("切换照片增强识别");check(waitText("重新识别这张图片？"),"Mode switching protects manually edited text");click("保留修改");check(has("请带上水杯"),"Cancelling mode change retains corrected text");clickDescription("用识别文字生成事项");check(waitText("新建事项")&&has("参加读书交流会"),"Recognized text uses original task editor");check(has("09:00—10:30")&&has("教学楼301教室"),"Actual OCR preserves interval and classroom for parser");try(Store store=new Store(c)){check(store.all().size()==baseline,"Recognition never auto-saves a task");}capture(c,"ocr-task-proof.png");click("取消");setEdit(1,"");
        clickDescription("从图片识别事项");check(waitText("图片识别"),"OCR can reopen");choose(Uri.parse("content://cn.shixu.app.missing/image"));check(waitText("无法读取这张图片")&&!createEnabled(),"Unreadable URI returns recoverable error");
        Bitmap blank=Bitmap.createBitmap(640,480,Bitmap.Config.ARGB_8888);blank.eraseColor(Color.WHITE);Uri blankUri=save(c,png(blank),"image/png",cleanup);blank.recycle();choose(blankUri);check(waitText("没有识别到文字")&&!createEnabled(),"Blank image does not create nonsense task");choose(normal);check(waitText("识别完成，请核对文字")&&createEnabled(),"Choosing valid image recovers from errors");click("关闭");
        Matrix turn=new Matrix();turn.postRotate(-90);Bitmap sideways=Bitmap.createBitmap(image,0,0,image.getWidth(),image.getHeight(),turn,true);File jpeg=new File(c.getCacheDir(),"ocr-exif-fixture.jpg");try(FileOutputStream out=new FileOutputStream(jpeg)){sideways.compress(Bitmap.CompressFormat.JPEG,95,out);}sideways.recycle();android.media.ExifInterface exif=new android.media.ExifInterface(jpeg.toString());exif.setAttribute(android.media.ExifInterface.TAG_ORIENTATION,String.valueOf(android.media.ExifInterface.ORIENTATION_ROTATE_90));exif.saveAttributes();Uri rotated=save(c,java.nio.file.Files.readAllBytes(jpeg.toPath()),"image/jpeg",cleanup);String rotatedText=recognize(c,rotated,true);check(rotatedText.replaceAll("\\s+","").contains("读书交流会"),"JPEG EXIF orientation is applied before OCR");jpeg.delete();image.recycle();
        boolean[] called={false};OcrEngine.Job cancelled=OcrEngine.recognize(c,normal,new OcrEngine.Listener(){public void preview(Bitmap b){called[0]=true;}public void text(String s){called[0]=true;}public void error(String s){called[0]=true;}});cancelled.cancel();pause();check(!called[0],"Cancelled recognition does not update abandoned screen");try(Store store=new Store(c)){check(store.all().size()==baseline,"OCR cancellation and errors preserve all user records");}
        results.putString("result","PASS: "+checks+" offline Chinese OCR, picker, correction, interval/location extraction, EXIF, errors and cancellation checks");
    }catch(Throwable error){StringWriter trace=new StringWriter();error.printStackTrace(new PrintWriter(trace));results.putString("error",trace.toString());outcome=Activity.RESULT_CANCELED;}finally{for(Uri uri:cleanup)try{c.getContentResolver().delete(uri,null,null);}catch(RuntimeException ignored){}}finish(outcome,results);}
}
